                </div>
              </div>

              <div className="mb-4 pt-4 border-t border-slate-700">
                <div className="text-xs text-slate-500 mb-1">Specialties</div>
                <div className="text-sm text-slate-300">{tutor.specialty}</div>
              </div>

              <button
                onClick={() => handleStartSession(tutor.id, tutor.subject)}
                className="w-full px-4 py-3 bg-slate-700 hover:bg-slate-600 text-slate-100 rounded-lg font-semibold text-sm transition-all duration-200 flex items-center justify-center gap-2 group-hover:shadow-lg"
              >
                Start Session
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
                </svg>
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );

  return (
    <div className="flex min-h-screen bg-slate-900">

      {/* Achievement Toast */}
      {showAchievement && (
        <div className="fixed top-6 right-6 z-50 bg-slate-800 border border-slate-700 rounded-lg shadow-2xl px-5 py-4 max-w-sm animate-bounce">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-green-900/30 border border-green-700 rounded-lg flex items-center justify-center">
              <svg className="w-5 h-5 text-green-400" fill="currentColor" viewBox="0 0 20 20">
                <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
              </svg>
            </div>
            <div>
              <div className="font-semibold text-slate-100 text-sm">Achievement Unlocked</div>
              <div className="text-xs text-slate-400 mt-0.5">5 Sessions Completed!</div>
            </div>
          </div>
        </div>
      )}

      {/* Sidebar */}
      <aside className="w-72 bg-slate-950 border-r border-slate-800 flex flex-col">
        <div className="p-6 border-b border-slate-800">
          <h1 className="text-2xl font-bold text-slate-100">Saarthi</h1>
          <p className="text-xs text-slate-500 mt-1">AI Learning Platform</p>
        </div>

        <div className="flex-1 p-4">
          <nav className="space-y-2">
            <button 
              onClick={() => setActiveView('dashboard')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-medium text-sm transition-colors ${
                activeView === 'dashboard'
                  ? 'bg-slate-800 text-slate-100'
                  : 'text-slate-400 hover:text-slate-200 hover:bg-slate-900'
              }`}
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" />
              </svg>
              Dashboard
            </button>

            <button 
              onClick={() => setActiveView('history')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-medium text-sm transition-colors ${
                activeView === 'history'
                  ? 'bg-slate-800 text-slate-100'
                  : 'text-slate-400 hover:text-slate-200 hover:bg-slate-900'
              }`}
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              History
              {sessions.length > 0 && (
                <span className="ml-auto px-2 py-0.5 bg-slate-700 text-slate-300 text-xs font-semibold rounded-full">
                  {sessions.length}
                </span>
              )}
            </button>

            <button 
              onClick={() => setActiveView('notes')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg font-medium text-sm transition-colors ${
                activeView === 'notes'
                  ? 'bg-slate-800 text-slate-100'
                  : 'text-slate-400 hover:text-slate-200 hover:bg-slate-900'
              }`}
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
              </svg>
              Notes
              {JSON.parse(localStorage.getItem('quickNotes') || '[]').length > 0 && (
                <span className="ml-auto px-2 py-0.5 bg-slate-700 text-slate-300 text-xs font-semibold rounded-full">
                  {JSON.parse(localStorage.getItem('quickNotes') || '[]').length}
                </span>
              )}
            </button>
          </nav>

          {/* Quick Stats in Sidebar */}
          <div className="mt-6 p-4 bg-slate-900 rounded-lg border border-slate-800">
            <div className="text-xs text-slate-500 mb-3 font-medium uppercase tracking-wide">This Week</div>
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-xs text-slate-400">Sessions</span>
                <span className="text-sm font-bold text-slate-200">{sessions.filter(s => {
                  const sessionDate = new Date(s.created_at);
                  const weekAgo = new Date();
                  weekAgo.setDate(weekAgo.getDate() - 7);
                  return sessionDate >= weekAgo;
                }).length}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-xs text-slate-400">Hours</span>
                <span className="text-sm font-bold text-slate-200">{totalHours}h</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-xs text-slate-400">Streak</span>
                <span className="text-sm font-bold text-green-400">{streak} days</span>
              </div>
            </div>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800">
          <div className="flex items-center gap-3 px-4 py-3 bg-slate-900 rounded-lg mb-3">
            <div className="w-10 h-10 bg-slate-700 rounded-lg flex items-center justify-center text-slate-200 font-semibold">
              {user?.name?.charAt(0)?.toUpperCase() || 'S'}
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-sm font-semibold text-slate-200 truncate">{user?.name || 'Student'}</div>
              <div className="text-xs text-slate-500 truncate">{user?.email}</div>
            </div>
          </div>
          <button 
            onClick={handleLogout}
            className="w-full px-4 py-2.5 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-lg font-medium text-sm transition-colors flex items-center justify-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
            </svg>
            Logout
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">
        {activeView === 'dashboard' && renderDashboardView()}
        {activeView === 'history' && renderHistoryView()}
        {activeView === 'notes' && renderNotesView()}
      </main>
    </div>
  );
}
